# Initially generated by GitHub Copilot.
"""Discover vendoring relationships from repo policy plus repo scans."""

from __future__ import annotations

from dataclasses import dataclass
from functools import lru_cache
from pathlib import Path

from mb_cmn import paths
from vendoring.repo_policy import OverridePolicy, RepoPolicy, load_policy

_MAM = paths.repo_root()
_REPOS = paths.repos_root()

# The verdict ``vendoring/compare.py`` reaches when a copy's bytes differ from its
# MAM-basics source but its newline-normalized bytes do not: same content, different
# line endings on disk.  Spelled once here because both that program and
# ``gen_inventory``'s notes-merging have to agree on it.
EOL_ONLY = "eol-only"

IDENTITY_VALUES = {"identical", EOL_ONLY, "DIFFERS", "MISSING-DEST", "MISSING-SRC"}


@dataclass(frozen=True)
class DerivedRelationship:
    file: str
    src_pkg: str
    dest_repo: str
    dest_path: str
    mechanism: str
    last_synced: str
    provenance_doc: str
    category: str
    notes: str

    def as_inventory_row(self) -> dict[str, str]:
        return {
            "file": self.file,
            "src_pkg": self.src_pkg,
            "dest_repo": self.dest_repo,
            "dest_path": self.dest_path,
            "mechanism": self.mechanism,
            "last_synced": self.last_synced,
            "provenance_doc": self.provenance_doc,
            "category": self.category,
            "notes": self.notes,
        }


def source_pkg_dirs() -> dict[str, str]:
    return dict(load_policy().source_pkg_dirs)


def ignored_repos() -> set[str]:
    policy = load_policy()
    return {repo_name for repo_name, repo in policy.repos.items() if repo.ignore}


@lru_cache(maxsize=1)
def _source_file_names() -> dict[str, set[str]]:
    policy = load_policy()
    names_by_pkg: dict[str, set[str]] = {}
    for src_pkg, rel_dir in policy.source_pkg_dirs.items():
        pkg_dir = _MAM / rel_dir
        if not pkg_dir.exists():
            raise ValueError(f"Missing source package dir for {src_pkg}: {pkg_dir}")
        names_by_pkg[src_pkg] = {
            path.name
            for path in pkg_dir.iterdir()
            if path.is_file() and path.suffix == ".py" and path.name != "__init__.py"
        }
    return names_by_pkg


def _repo_overrides() -> dict[str, dict[str, OverridePolicy]]:
    by_repo: dict[str, dict[str, OverridePolicy]] = {}
    for override in load_policy().overrides:
        by_repo.setdefault(override.dest_repo, {})[override.dest_path] = override
    return by_repo


def _scanned_dest_paths(
    repo_name: str, repo_policy: RepoPolicy
) -> list[tuple[str, str]]:
    source_names = _source_file_names()
    repo_path = _REPOS / repo_name
    if not repo_path.exists():
        raise ValueError(f"Missing destination repo: {repo_name}")

    discovered: list[tuple[str, str]] = []
    seen_dest_paths: set[str] = set()
    for src_pkg, roots in repo_policy.pkg_scan_roots.items():
        valid_names = source_names[src_pkg]
        for root in roots:
            root_path = repo_path / root
            if not root_path.exists():
                raise ValueError(f"Configured scan root does not exist: {root_path}")
            for path in sorted(root_path.iterdir()):
                if (
                    not path.is_file()
                    or path.suffix != ".py"
                    or path.name == "__init__.py"
                ):
                    continue
                if path.name not in valid_names:
                    continue
                dest_path = str(path.relative_to(repo_path)).replace("\\", "/")
                if dest_path in seen_dest_paths:
                    raise ValueError(
                        f"Duplicate discovered destination path in {repo_name}: {dest_path}"
                    )
                seen_dest_paths.add(dest_path)
                discovered.append((src_pkg, dest_path))
    return discovered


def _notes_text(value: str | None) -> str:
    return value or ""


def _build_row(
    repo_name: str,
    repo_policy: RepoPolicy,
    src_pkg: str,
    dest_path: str,
    override: OverridePolicy | None,
) -> DerivedRelationship:
    file_name = Path(dest_path).name
    return DerivedRelationship(
        file=file_name,
        src_pkg=src_pkg,
        dest_repo=repo_name,
        dest_path=dest_path,
        mechanism=(override.mechanism if override else None)
        or repo_policy.default_mechanism
        or "unknown",
        last_synced="",
        provenance_doc=(override.provenance_doc if override else None)
        or repo_policy.default_provenance_doc
        or "no",
        # No ``or "unknown"`` third fallback here, unlike mechanism and provenance_doc
        # above: ``repo_policy`` rejects a non-ignored repo that omits default_category
        # and rejects any value outside ``CATEGORY_VALUES``, and the caller skips the
        # ignored repos, so every row's category is a declared word.  The fallback that
        # stood here could only ever have fired on a policy the loader now refuses to
        # load, which made "unknown" a fifth category no repo could produce -- the same
        # half of the vocabulary problem as ``deferred``, at the other end (#60).
        category=(override.category if override else None)
        or repo_policy.default_category,
        notes=_notes_text(override.notes if override else None),
    )


@lru_cache(maxsize=1)
def discover_relationships() -> tuple[DerivedRelationship, ...]:
    policy = load_policy()
    source_names = _source_file_names()
    overrides_by_repo = _repo_overrides()
    relationships: list[DerivedRelationship] = []

    for repo_name, repo_policy in policy.repos.items():
        if repo_policy.ignore:
            continue
        override_map = dict(overrides_by_repo.get(repo_name, {}))
        seen_dest_paths: set[str] = set()

        for src_pkg, dest_path in _scanned_dest_paths(repo_name, repo_policy):
            override = override_map.pop(dest_path, None)
            row = _build_row(repo_name, repo_policy, src_pkg, dest_path, override)
            relationships.append(row)
            seen_dest_paths.add(dest_path)

        for dest_path, override in sorted(override_map.items()):
            if Path(dest_path).name not in source_names[override.src_pkg]:
                raise ValueError(
                    f"Override path {repo_name}/{dest_path} does not match a source file in {override.src_pkg}"
                )
            if dest_path in seen_dest_paths:
                raise ValueError(
                    f"Duplicate override target in {repo_name}: {dest_path}"
                )
            relationships.append(
                _build_row(
                    repo_name, repo_policy, override.src_pkg, dest_path, override
                )
            )
            seen_dest_paths.add(dest_path)

    return tuple(relationships)


def iter_inventory_seed_rows() -> list[dict[str, str]]:
    return [row.as_inventory_row() for row in discover_relationships()]


def _compare_hint_from_inventory_row(data: dict[str, str]) -> str:
    if data["category"] == "generated":
        return "generated"
    if data["category"] == "unmeasured":
        return "unmeasured"

    first_clause, sep, remainder = data["notes"].partition(";")
    if first_clause in IDENTITY_VALUES:
        return remainder.strip() if sep else ""
    return data["notes"]


def iter_compare_copies() -> list[tuple[str, str, str, str, str]]:
    return [
        (
            data["file"],
            data["src_pkg"],
            data["dest_repo"],
            data["dest_path"],
            _compare_hint_from_inventory_row(data),
        )
        for data in iter_inventory_seed_rows()
    ]


def provenance_dest_repos() -> list[str]:
    policy = load_policy()
    return [
        repo_name
        for repo_name, repo in policy.repos.items()
        if not repo.ignore and repo.scan_provenance
    ]
